import { set as idbSet } from "idb-keyval";
import { idbGetWithLegacyFallback } from "../lib/legacyBrandMigration";
import { create } from "zustand";
import type {
  CorpusEntry,
  InkStroke,
  KwicHit,
  LanguageInsight,
  NotePage,
  NoteSpace,
  PracticeTurnResponse,
  RoomObjectId,
  StrokePoint,
} from "@leafia/shared";
import { api } from "../lib/api";
import { createId } from "../lib/createId";
import {
  PRACTICE_SCENARIOS,
  practiceScenarioById,
} from "../data/practiceScenarios";
import {
  demoCorpus,
  demoKwic,
  demoPage,
  demoSpaces,
  fallbackInsight,
} from "../data/demo";

export type AITab = "meaning" | "collocations" | "context" | "corpus" | "use";
export type TimeOfDay = "day" | "night";
export type ToastState = { id: string; message: string } | null;
export type InkTool = InkStroke["tool"] | "select";

interface PracticeMessage {
  id: string;
  role: "user" | "assistant";
  text: string;
  textZh?: string;
  explanationZh?: string;
  feedback?: string;
}

interface StrokeHistory {
  future: InkStroke[];
}

interface LeafiaState {
  bootstrapped: boolean;
  apiOnline: boolean;
  deepseekConfigured: boolean;
  spaces: NoteSpace[];
  activeSpaceId: string;
  currentNoteId: string;
  currentPage: NotePage;
  strokes: InkStroke[];
  strokeHistory: StrokeHistory;
  inkTool: InkTool;
  inkColor: string;
  inkSize: number;
  corpus: CorpusEntry[];
  kwicHits: KwicHit[];
  selectedTerm: string;
  insight: LanguageInsight | null;
  insightLoading: boolean;
  aiOpen: boolean;
  aiTab: AITab;
  timeOfDay: TimeOfDay;
  selectedRoomObject: RoomObjectId | null;
  archiveOpen: boolean;
  practiceMessages: PracticeMessage[];
  practiceScenarioId: string;
  practiceCompleted: boolean;
  toast: ToastState;
  bootstrap: () => Promise<void>;
  setActiveSpace: (id: string) => void;
  loadPage: (noteId: string, pageId: string) => Promise<void>;
  savePage: (content: unknown) => Promise<void>;
  setInkTool: (tool: InkTool) => void;
  setInkColor: (color: string) => void;
  setInkSize: (size: number) => void;
  addStroke: (stroke: InkStroke) => void;
  removeStroke: (id: string) => void;
  undoStroke: () => void;
  redoStroke: () => void;
  clearStrokes: () => void;
  analyzeSelection: (
    term: string,
    contextBefore?: string,
    contextAfter?: string,
  ) => Promise<void>;
  openAI: (term?: string) => void;
  closeAI: () => void;
  setAITab: (tab: AITab) => void;
  addInsightToCorpus: () => Promise<void>;
  refreshCorpus: () => Promise<void>;
  searchKwic: (query: string) => Promise<void>;
  toggleFavorite: (id: string) => Promise<void>;
  removeCorpus: (id: string) => Promise<void>;
  setTimeOfDay: (time: TimeOfDay) => void;
  selectRoomObject: (id: RoomObjectId | null) => void;
  setArchiveOpen: (open: boolean) => void;
  processImage: (file: File) => Promise<void>;
  resetPractice: () => void;
  sendPracticeMessage: (message: string) => Promise<void>;
  setPracticeScenario: (scenarioId: string) => void;
  showToast: (message: string) => void;
  clearToast: () => void;
}

const initialPage = structuredClone(demoPage);
const DEFAULT_SCENARIO_ID = PRACTICE_SCENARIOS[0]!.id;

function initialPracticeMessages(scenarioId: string): PracticeMessage[] {
  const scenario = practiceScenarioById(scenarioId);
  return [
    {
      id: `practice-intro-${scenario.id}`,
      role: "assistant",
      text: scenario.opening,
      textZh: scenario.openingZh,
      explanationZh: scenario.openingExplanationZh,
    },
  ];
}

function fileToBase64(file: File) {
  return new Promise<string>((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => {
      const result = String(reader.result ?? "");
      resolve(result.slice(result.indexOf(",") + 1));
    };
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });
}

function pageStorageKey(noteId: string, pageId: string) {
  return `leafia:page:${noteId}:${pageId}`;
}

export const useLeafia = create<LeafiaState>((set, get) => ({
  bootstrapped: false,
  apiOnline: false,
  deepseekConfigured: false,
  spaces: demoSpaces,
  activeSpaceId: "academic",
  currentNoteId: "note-academic-1",
  currentPage: initialPage,
  strokes: [],
  strokeHistory: { future: [] },
  inkTool: "select",
  inkColor: "#1487b1",
  inkSize: 3,
  corpus: demoCorpus,
  kwicHits: demoKwic,
  selectedTerm: "competitive edge",
  insight: fallbackInsight("competitive edge"),
  insightLoading: false,
  aiOpen: false,
  aiTab: "meaning",
  timeOfDay: "day",
  selectedRoomObject: null,
  archiveOpen: false,
  practiceMessages: initialPracticeMessages(DEFAULT_SCENARIO_ID),
  practiceScenarioId: DEFAULT_SCENARIO_ID,
  practiceCompleted: false,
  toast: null,

  async bootstrap() {
    if (get().bootstrapped) return;
    try {
      const [health, spaces, corpus] = await Promise.all([
        api.health(),
        api.spaces(),
        api.corpus(),
      ]);
      set({
        apiOnline: true,
        deepseekConfigured: health.deepseekConfigured,
        spaces: spaces.spaces,
        corpus: corpus.entries,
      });
    } catch {
      set({ apiOnline: false });
    }
    set({ bootstrapped: true });
  },

  setActiveSpace(id) {
    set({ activeSpaceId: id });
  },

  async loadPage(noteId, pageId) {
    const local = await idbGetWithLegacyFallback<NotePage>(
      pageStorageKey(noteId, pageId),
    );
    if (local) {
      set({
        currentNoteId: noteId,
        currentPage: local,
        strokes: (local as NotePage & { strokes?: InkStroke[] }).strokes ?? [],
      });
      return;
    }
    try {
      const response = await api.page(noteId, pageId);
      set({
        currentNoteId: noteId,
        currentPage: response.page,
        strokes:
          (response.page as NotePage & { strokes?: InkStroke[] }).strokes ?? [],
      });
    } catch {
      set({
        currentNoteId: noteId,
        currentPage: structuredClone(demoPage),
        strokes: [],
      });
    }
  },

  async savePage(content) {
    const current = get().currentPage;
    const next: NotePage = {
      ...current,
      content,
      version: current.version + 1,
      updatedAt: new Date().toISOString(),
    };
    await idbSet(
      pageStorageKey(next.noteId, next.id),
      {
        ...next,
        strokes: get().strokes,
      },
    ).catch(() => undefined);
    set({ currentPage: next });
    try {
      const response = await api.savePage(next.noteId, next.id, {
        ...next,
        baseVersion: current.version,
      });
      set({ currentPage: response.page, apiOnline: true });
    } catch {
      set({ apiOnline: false });
    }
  },

  setInkTool(tool) {
    set({ inkTool: tool });
  },

  setInkColor(color) {
    set({ inkColor: color });
  },

  setInkSize(size) {
    set({ inkSize: size });
  },

  addStroke(stroke) {
    set((state) => ({
      strokes: [...state.strokes, stroke],
      strokeHistory: { future: [] },
    }));
  },

  removeStroke(id) {
    set((state) => ({
      strokes: state.strokes.filter((stroke) => stroke.id !== id),
    }));
  },

  undoStroke() {
    set((state) => {
      const last = state.strokes.at(-1);
      if (!last) return state;
      return {
        strokes: state.strokes.slice(0, -1),
        strokeHistory: {
          future: [last, ...state.strokeHistory.future],
        },
      };
    });
  },

  redoStroke() {
    set((state) => {
      const [next, ...remaining] = state.strokeHistory.future;
      if (!next) return state;
      return {
        strokes: [...state.strokes, next],
        strokeHistory: { future: remaining },
      };
    });
  },

  clearStrokes() {
    set({ strokes: [], strokeHistory: { future: [] } });
  },

  async analyzeSelection(term, contextBefore, contextAfter) {
    const selected = term.trim();
    if (!selected) return;
    set({
      selectedTerm: selected,
      insightLoading: true,
      aiOpen: true,
      aiTab: "meaning",
    });
    try {
      const response = await api.insight({
        noteId: get().currentNoteId,
        pageId: get().currentPage.id,
        selectedText: selected,
        contextBefore,
        contextAfter,
        locale: "zh-CN",
        sourceSpan: {
          noteId: get().currentNoteId,
          pageId: get().currentPage.id,
          blockId: "editor-selection",
        },
      });
      set({
        insight: response.insight,
        insightLoading: false,
        apiOnline: true,
      });
    } catch {
      set({
        insight: fallbackInsight(selected, {
          noteId: get().currentNoteId,
          pageId: get().currentPage.id,
          blockId: "editor-selection",
        }),
        insightLoading: false,
        apiOnline: false,
      });
    }
  },

  openAI(term) {
    if (term) {
      void get().analyzeSelection(term);
      return;
    }
    set({ aiOpen: true });
  },

  closeAI() {
    set({ aiOpen: false });
  },

  setAITab(tab) {
    set({ aiTab: tab, aiOpen: true });
  },

  async addInsightToCorpus() {
    const insight = get().insight;
    if (!insight) return;
    try {
      const response = await api.addCorpus({
        insight,
        sourceLabel:
          get().spaces.find((space) => space.id === get().activeSpaceId)?.title ??
          "Academic Reading",
        tags: [],
      });
      set((state) => ({
        corpus: [
          response.entry,
          ...state.corpus.filter((item) => item.id !== response.entry.id),
        ],
      }));
    } catch {
      const entry: CorpusEntry = {
        id: `local-${createId()}`,
        term: insight.term,
        normalizedTerm: insight.term.toLowerCase(),
        meaningsZh: insight.meaningsZh,
        definitionEn: insight.definitionEn,
        collocations: insight.collocations,
        source:
          insight.sourceSpan ?? {
            noteId: get().currentNoteId,
            pageId: get().currentPage.id,
          },
        sourceLabel:
          get().spaces.find((space) => space.id === get().activeSpaceId)?.title ??
          "Academic Reading",
        tags: [],
        favorite: false,
        createdAt: new Date().toISOString(),
      };
      set((state) => ({ corpus: [entry, ...state.corpus] }));
    }
    get().showToast(`已收入语料：${insight.term}`);
  },

  async refreshCorpus() {
    try {
      const response = await api.corpus();
      set({ corpus: response.entries, apiOnline: true });
    } catch {
      set({ apiOnline: false });
    }
  },

  async searchKwic(query) {
    if (!query.trim()) {
      set({ kwicHits: [] });
      return;
    }
    try {
      const response = await api.kwic(query);
      set({ kwicHits: response.hits, apiOnline: true });
    } catch {
      const lower = query.toLowerCase();
      set({
        kwicHits: demoKwic.filter(
          (hit) =>
            hit.keyword.toLowerCase().includes(lower) ||
            `${hit.left} ${hit.keyword} ${hit.right}`
              .toLowerCase()
              .includes(lower),
        ),
        apiOnline: false,
      });
    }
  },

  async toggleFavorite(id) {
    const current = get().corpus.find((entry) => entry.id === id);
    if (!current) return;
    set((state) => ({
      corpus: state.corpus.map((entry) =>
        entry.id === id ? { ...entry, favorite: !entry.favorite } : entry,
      ),
    }));
    try {
      await api.favoriteCorpus(id);
    } catch {
      set((state) => ({
        corpus: state.corpus.map((entry) =>
          entry.id === id ? current : entry,
        ),
      }));
    }
  },

  async removeCorpus(id) {
    const current = get().corpus;
    set({ corpus: current.filter((entry) => entry.id !== id) });
    try {
      await api.removeCorpus(id);
    } catch {
      set({ corpus: current });
    }
  },

  setTimeOfDay(time) {
    set({ timeOfDay: time });
  },

  selectRoomObject(id) {
    set({ selectedRoomObject: id });
  },

  setArchiveOpen(open) {
    set({ archiveOpen: open });
  },

  async processImage(file) {
    get().showToast("正在读取图片中的英语表达…");
    const base64 = await fileToBase64(file);
    try {
      const response = await api.vision({
        noteId: get().currentNoteId,
        pageId: get().currentPage.id,
        imageBase64: base64,
        mediaType: file.type as
          | "image/jpeg"
          | "image/png"
          | "image/webp"
          | "image/gif",
        prompt:
          "Read this English study image and extract high-value reusable expressions.",
      });
      const first = response.insights[0] ?? fallbackInsight("image note");
      set({
        selectedTerm: first.term,
        insight: first,
        aiOpen: true,
        aiTab: "meaning",
        apiOnline: true,
      });
      get().showToast(`已从图片中发现 ${response.insights.length} 个表达`);
    } catch {
      const fallback = fallbackInsight("image note");
      set({
        selectedTerm: fallback.term,
        insight: fallback,
        aiOpen: true,
        aiTab: "meaning",
        apiOnline: false,
      });
      get().showToast("图片分析暂不可用，已切换到本地示例");
    }
  },

  resetPractice() {
    const scenarioId = get().practiceScenarioId;
    set({
      practiceMessages: initialPracticeMessages(scenarioId),
      practiceCompleted: false,
    });
  },

  setPracticeScenario(scenarioId) {
    const scenario = practiceScenarioById(scenarioId);
    set({
      practiceScenarioId: scenario.id,
      practiceMessages: initialPracticeMessages(scenario.id),
      practiceCompleted: false,
    });
  },

  async sendPracticeMessage(message) {
    const sessionId = "practice-local";
    const scenario = practiceScenarioById(get().practiceScenarioId);
    const userMessage: PracticeMessage = {
      id: createId(),
      role: "user",
      text: message,
    };
    set((state) => ({
      practiceMessages: [...state.practiceMessages, userMessage],
    }));
    try {
      const response = await api.practice({
        sessionId,
        message,
        targetExpressions: scenario.targetExpressions,
        scenario: scenario.scenario,
      });
      appendPracticeReply(response, set);
    } catch {
      appendPracticeReply(
        {
          sessionId,
          reply:
            "That is a thoughtful answer. What would you choose to do next, and why?",
          replyZh: "这是一个很有想法的回答。接下来你会怎么选择，为什么？",
          explanationZh:
            "可以继续使用 “I would choose to ...” 或 “What matters most is ...” 来补充理由。",
          usedExpressions: [scenario.targetExpressions[0] ?? "in my opinion"],
          feedback: "表达清楚，可以再补充一个具体理由。",
          suggestions: [
            "We would track retention and repeat use.",
            "We would test demand before scaling.",
          ],
          completed: false,
        },
        set,
      );
    }
  },

  showToast(message) {
    const id = createId();
    set({ toast: { id, message } });
    window.setTimeout(() => {
      if (get().toast?.id === id) set({ toast: null });
    }, 2600);
  },

  clearToast() {
    set({ toast: null });
  },
}));

function appendPracticeReply(
  response: PracticeTurnResponse,
  set: (
    partial:
      | Partial<LeafiaState>
      | ((state: LeafiaState) => Partial<LeafiaState>),
  ) => void,
) {
  set((state) => ({
    practiceMessages: [
      ...state.practiceMessages,
      {
        id: createId(),
        role: "assistant" as const,
        text: response.reply,
        textZh: response.replyZh,
        explanationZh: response.explanationZh,
        feedback: response.feedback,
      },
    ],
    practiceCompleted: response.completed,
  }));
}

export function pointsForStroke(points: StrokePoint[]) {
  return points;
}
