import { gsap } from "gsap";
import { useEffect, useRef } from "react";
import { usePrefersReducedMotion } from "../../motion/usePrefersReducedMotion";
import "./site-intro.css";

/**
 * Leafia 的产品开场幕布。
 *
 * 它不再跟随路由自动出现，只由目录底部的「关于产品 / Leafia」手动唤出：
 * 谱线展开、音符浮入、Leafia 字母升起，短暂停留后主动收场，把页面交还给
 * 用户。reduced-motion 下直接完成回调，不用动效堵住页面。
 */
const WORDMARK = "Leafia";
const NOTES = ["♪", "♩", "♫", "♬", "♩"];
const HOLD_AFTER_ENTER_MS = 680;

interface SiteIntroProps {
  open: boolean;
  onFinished: () => void;
  /**
   * 入场播完、收场（680ms 停留 + 退场）开始前后的那个瞬间。App 在这里把
   * 路由先挂到幕布后面：welcome 的首帧渲染与它的主线程开销都发生在幕布里，
   * 而不是幕布揭开之后——揭幕那一刻页面已经就位。
   */
  onExiting?: () => void;
}

export function SiteIntro({ open, onFinished, onExiting }: SiteIntroProps) {
  const prefersReducedMotion = usePrefersReducedMotion();
  const rootRef = useRef<HTMLDivElement>(null);
  const onFinishedRef = useRef(onFinished);
  const onExitingRef = useRef(onExiting);

  useEffect(() => {
    onFinishedRef.current = onFinished;
    onExitingRef.current = onExiting;
  }, [onFinished, onExiting]);

  useEffect(() => {
    if (!open) return undefined;
    if (prefersReducedMotion) {
      onExitingRef.current?.();
      onFinishedRef.current();
      return undefined;
    }

    const root = rootRef.current;
    if (!root) return undefined;

    const notes = root.querySelectorAll(".site-intro__note");
    const staffLines = root.querySelectorAll(".site-intro__staff-line");
    const letters = root.querySelectorAll(".site-intro__letter-glyph");
    const wash = root.querySelector(".site-intro__wash");

    // The stylesheet parks each glyph below its mask with a percentage
    // translate. Put that value onto the channel GSAP's entrance animates.
    gsap.set(letters, { y: 0, yPercent: 118, rotate: 2.5 });

    let enter: gsap.core.Timeline | null = null;
    let exit: gsap.core.Timeline | null = null;
    let holdTimer = 0;

    const context = gsap.context(() => {
      const enterTimeline = gsap.timeline({
        defaults: { ease: "power3.out" },
        paused: true,
      });
      enter = enterTimeline;
      enterTimeline
        .fromTo(
          wash,
          { clipPath: "ellipse(0% 0% at 86% 50%)" },
          {
            clipPath: "ellipse(120% 130% at 86% 50%)",
            duration: 0.84,
            ease: "power4.out",
          },
        )
        .fromTo(
          staffLines,
          {
            scaleX: 0,
            transformOrigin: (index: number) =>
              index % 2 === 0 ? "left center" : "right center",
          },
          { scaleX: 1, duration: 0.56, stagger: 0.05 },
          "-=0.5",
        )
        .fromTo(
          notes,
          {
            opacity: 0,
            x: 150,
            y: (index: number) => 42 + index * 18,
            rotate: (index: number) => -12 + index * 7,
            scale: 0.42,
          },
          {
            opacity: 1,
            x: 0,
            y: 0,
            rotate: (index: number) => -7 + index * 4,
            scale: 1,
            duration: 0.66,
            stagger: 0.082,
            ease: "back.out(1.5)",
          },
          "-=0.4",
        )
        .fromTo(
          letters,
          { yPercent: 118, rotate: 2.5 },
          { yPercent: 0, rotate: 0, duration: 0.62, stagger: 0.038 },
          "-=0.62",
        )
        .fromTo(
          root.querySelector(".site-intro__rule"),
          { scaleX: 0 },
          { scaleX: 1, duration: 0.5, ease: "power2.out" },
          "-=0.34",
        )
        .fromTo(
          root.querySelector(".site-intro__tagline"),
          { opacity: 0, y: 20 },
          { opacity: 1, y: 0, duration: 0.46 },
          "-=0.38",
        )
        .fromTo(
          root.querySelector(".site-intro__eyebrow"),
          { opacity: 0, x: -14 },
          { opacity: 1, x: 0, duration: 0.36 },
          "-=0.4",
        );

      const exitTimeline = gsap.timeline({
        paused: true,
        onComplete: () => onFinishedRef.current(),
      });
      exit = exitTimeline;
      exitTimeline
        .to(notes, {
          y: -36,
          rotate: (index: number) => -4 + index * 6,
          duration: 0.48,
          stagger: 0.035,
        })
        .to(
          root.querySelector(".site-intro__copy"),
          { y: -34, opacity: 0, duration: 0.46 },
          "-=0.24",
        )
        .to(
          wash,
          {
            clipPath: "ellipse(0% 0% at 86% 8%)",
            duration: 0.62,
            ease: "power3.inOut",
          },
          "-=0.28",
        )
        .to(root, { autoAlpha: 0, duration: 0.24 }, "-=0.12");

      enterTimeline.eventCallback("onComplete", () => {
        // 退场之前（停留期间，幕布还完整盖着）就让 App 开始交接：路由挂载
        // 与 welcome 首帧的渲染开销藏在这段停留和之后的退场动画背后。
        onExitingRef.current?.();
        holdTimer = window.setTimeout(
          () => exitTimeline.play(0),
          HOLD_AFTER_ENTER_MS,
        );
      });
    }, root);

    const startTimer = window.setTimeout(() => {
      enter?.play(0);
    }, 80);

    return () => {
      window.clearTimeout(startTimer);
      window.clearTimeout(holdTimer);
      enter?.kill();
      exit?.kill();
      context.revert();
    };
  }, [open, prefersReducedMotion]);

  if (!open) return null;

  return (
    <div ref={rootRef} className="site-intro" aria-hidden="true">
      <div className="site-intro__wash">
        <div className="site-intro__staff">
          {Array.from({ length: 5 }, (_, index) => (
            <i key={index} className="site-intro__staff-line" />
          ))}
        </div>
        <div className="site-intro__notes">
          {NOTES.map((note, index) => (
            <span
              key={`${note}-${index}`}
              className="site-intro__note"
              data-note={index}
            >
              {note}
            </span>
          ))}
        </div>
      </div>
      <div className="site-intro__type site-intro__copy">
        <small className="site-intro__eyebrow">01 · Language in motion</small>
        <span className="site-intro__word">
          {WORDMARK.split("").map((letter, index) => (
            <span key={`${letter}-${index}`} className="site-intro__letter">
              <i className="site-intro__letter-glyph">{letter}</i>
            </span>
          ))}
        </span>
        <span className="site-intro__rule" />
        <em className="site-intro__tagline">where language finds its rhythm</em>
      </div>
    </div>
  );
}

export default SiteIntro;
