export function fallbackInsight(
  term: string,
  sourceSpan?: LanguageInsight["sourceSpan"],
): LanguageInsight {
  const known = demoCorpus.find(
    (entry) => entry.normalizedTerm === term.toLowerCase(),
  );
  if (known) {
    return {
      term: known.term,
      lemma: known.term,
      meaningsZh: known.meaningsZh,
      definitionEn: known.definitionEn,
      collocations: known.collocations,
      examples: [],
      usageNotes: ["This expression is already part of your personal corpus."],
      sourceSpan,
      provider: "mock",
      model: "local-fallback",
    };
  }
  return {
    term,
    lemma: term,
    meaningsZh: ["值得学习的表达"],
    definitionEn:
      "A useful expression whose meaning depends on the surrounding context.",
    collocations: [`use ${term}`, `build on ${term}`, `make ${term} work`],
    examples: [
      {
        text: `The writer uses “${term}” to make the argument more precise.`,
        translationZh: `作者用“${term}”让论证更加准确。`,
      },
    ],
    usageNotes: ["The local fallback provider is active."],
    sourceSpan,
    provider: "mock",
    model: "local-fallback",
  };
}

