/**
 * 罩在界面上的一层雾玻璃（GlassVeil）
 *
 * 顶栏、侧栏、抽屉、贴边面板这些「贴在内容外面的壳」用它。和 GlassPlate 的分工
 * 很干脆：板是能摆的（宽高自己定、里面装得下东西），罩是壳 —— 多大由里面装的
 * 东西和调用方的布局说了算，它只管材质。
 *
 * 三处是自己的做法：
 *   · 雾面浓淡、边线、扫光的颜色全走 --veil-* 变量，宿主样式想改就改变量，
 *     不用跟选择器比特异性；
 *   · 两层伪元素挂在 z-index:-1（宿主 isolation:isolate 兜着），压在底色之上、
 *     内容之下 —— 里面放按钮、输入框、绝对定位的角标都天然在玻璃上面；
 *   · 指针那道光按帧走：pointermove 只记坐标，下一帧才量一次尺寸、写一次变量，
 *     指针飘得再快也不重复量布局。进壳才亮、出壳就暗回去，触屏不凑这个热闹。
 */
import {
  useCallback,
  useEffect,
  useRef,
  type ComponentType,
  type HTMLAttributes,
  type PointerEvent as ReactPointerEvent,
  type ReactNode,
  type Ref,
} from "react";
import { cn } from "../../lib/cn";
import "./glass-veil.css";

export type GlassVeilTone = "light" | "dark";
export type GlassVeilStrength = "soft" | "strong";

export interface GlassVeilProps extends HTMLAttributes<HTMLElement> {
  /** 壳用什么标签：顶栏 header、侧栏 aside、导航 nav、抽屉 div …… */
  as?: GlassVeilHost;
  /** 壳的底色走哪一套：浅色随主题，dark 是自个儿压暗的那档。 */
  tone?: GlassVeilTone;
  /** 雾有多厚：soft 是常规，strong 给抽屉、浮层那种更实的。 */
  strength?: GlassVeilStrength;
  /** 指针扫过时那道亮光跟不跟着走。 */
  glint?: boolean;
  children?: ReactNode;
}

/** 根标签通常就是这几个壳标签，也可以直接给个组件。 */
export type GlassVeilElement =
  | "aside"
  | "div"
  | "footer"
  | "form"
  | "header"
  | "nav"
  | "section";

export type GlassVeilHost = GlassVeilElement | ComponentType<GlassVeilHostProps>;

/**
 * 根标签上会放的那几样。
 * 直接写一串标签名挂进 JSX，TS 会把这一百多个标签一起算、最后把 props 收成
 * never；这里按我们真正往上放的东西说清楚，类型就站得住了（同 RevealText）。
 */
interface GlassVeilHostProps extends HTMLAttributes<HTMLElement> {
  ref?: Ref<HTMLElement>;
}

export function GlassVeil({
  as = "div",
  children,
  className,
  tone = "light",
  strength = "soft",
  glint = true,
  onPointerMove,
  onPointerEnter,
  onPointerLeave,
  ...rest
}: GlassVeilProps) {
  const hostRef = useRef<HTMLElement>(null);
  /** 指针最新落在哪儿（client 坐标）。 */
  const atRef = useRef({ x: 0, y: 0, known: false });
  const frameRef = useRef(0);

  /** 一帧最多量一次尺寸、写一次变量。 */
  const paint = useCallback(() => {
    frameRef.current = 0;
    const host = hostRef.current;
    const at = atRef.current;
    if (!host || !at.known) return;
    const rect = host.getBoundingClientRect();
    if (!rect.width || !rect.height) return;
    host.style.setProperty("--veil-x", `${(((at.x - rect.left) / rect.width) * 100).toFixed(2)}%`);
    host.style.setProperty("--veil-y", `${(((at.y - rect.top) / rect.height) * 100).toFixed(2)}%`);
  }, []);

  const schedule = () => {
    if (!frameRef.current) frameRef.current = window.requestAnimationFrame(paint);
  };

  useEffect(
    () => () => {
      if (frameRef.current) window.cancelAnimationFrame(frameRef.current);
      frameRef.current = 0;
    },
    [],
  );

  const handlePointerMove = (event: ReactPointerEvent<HTMLElement>) => {
    /* 手指没有「扫过」这一说：戳一下就亮一下反而碍眼，触屏不参与。 */
    if (glint && event.pointerType !== "touch") {
      atRef.current = { x: event.clientX, y: event.clientY, known: true };
      schedule();
    }
    onPointerMove?.(event);
  };

  const handlePointerEnter = (event: ReactPointerEvent<HTMLElement>) => {
    if (glint && event.pointerType !== "touch") {
      atRef.current = { x: event.clientX, y: event.clientY, known: true };
      schedule();
      hostRef.current?.style.setProperty("--veil-lit", "1");
    }
    onPointerEnter?.(event);
  };

  const handlePointerLeave = (event: ReactPointerEvent<HTMLElement>) => {
    /* 撤掉行内值，CSS 里那档「歇着时的亮度」自己接上。 */
    if (glint) hostRef.current?.style.removeProperty("--veil-lit");
    onPointerLeave?.(event);
  };

  const Tag = as as ComponentType<GlassVeilHostProps>;

  return (
    <Tag
      {...rest}
      ref={hostRef}
      className={cn(
        "glass-veil",
        strength === "strong" && "is-thick",
        tone === "dark" && "is-dark",
        className,
      )}
      onPointerMove={handlePointerMove}
      onPointerEnter={handlePointerEnter}
      onPointerLeave={handlePointerLeave}
    >
      <span className="glass-veil__content">{children}</span>
    </Tag>
  );
}

export default GlassVeil;
