import {
  ArrowLeft,
  ArrowRight,
  Check,
  LoaderCircle,
  LogOut,
  Mail,
  ShieldCheck,
  UserRound,
  X,
} from "lucide-react";
import {
  useEffect,
  useId,
  useRef,
  useState,
  type FormEvent,
  type ReactNode,
} from "react";
import { createPortal } from "react-dom";
import { Link, useNavigate } from "react-router-dom";
import { useLeafiaAccount, useAccountStore } from "../../lib/auth";
import {
  isStrongPassword,
  isValidEmail,
  normalizeEmail,
} from "../../lib/authForm";
import { cn } from "../../lib/cn";
import { maskEmail } from "../../lib/localAccount";
import { PasscodeField } from "./PasscodeField";
import "./auth-dialog.css";

type AuthView = "signin" | "register";
type LoginMode = "password" | "email";
type CodeStatus = "idle" | "error" | "success";

interface AuthDialogProps {
  open: boolean;
  onClose: () => void;
  initialView?: AuthView;
}

function FieldIcon({ children }: { children: ReactNode }) {
  return (
    <span className="auth-dialog__field-icon" aria-hidden="true">
      {children}
    </span>
  );
}

function CodeField({
  label,
  value,
  status,
  disabled,
  autoFocus,
  ariaLabel,
  onChange,
  onComplete,
}: {
  label: string;
  value: string;
  status: CodeStatus;
  disabled?: boolean;
  autoFocus?: boolean;
  ariaLabel: string;
  onChange: (value: string) => void;
  onComplete?: (value: string) => void;
}) {
  return (
    <label className="auth-dialog__code-field">
      <span>{label}</span>
      <PasscodeField
        length={6}
        value={value}
        status={status}
        disabled={disabled}
        autoFocus={autoFocus}
        mask
        gap={8}
        radius={10}
        label={ariaLabel}
        tone={{
          accent: "#8f7fc0",
          ink: "#51466f",
          plate: "#e8e3f1",
          digit: "#342c36",
          danger: "#a25151",
        }}
        onChange={(next: string) => onChange(next)}
        onComplete={(code: string) => onComplete?.(code)}
      />
    </label>
  );
}

export function AuthDialog({
  open,
  onClose,
  initialView = "signin",
}: AuthDialogProps) {
  const account = useLeafiaAccount();
  const navigate = useNavigate();
  const titleId = useId();
  const restoreFocusRef = useRef<HTMLElement | null>(null);
  const emailRef = useRef<HTMLInputElement>(null);
  /**
   * 关窗那一下走 ref，不走依赖数组：下面那支「开窗时重置」的 effect 每次
   * 重跑都会 clearError()，而调用方大多把 onClose 写成内联箭头函数 ——
   * 谁要是碰巧又订着整个账号 store，一次 set 就能让整页重画、生出一个
   * 新的 onClose，effect 再重跑，来回就是死循环（React #185 白屏）。
   * ref 让 Escape 永远读到最新的回调，又不会把 onClose 拖进依赖里。
   */
  const onCloseRef = useRef(onClose);
  useEffect(() => {
    onCloseRef.current = onClose;
  }, [onClose]);

  const [view, setView] = useState<AuthView>(initialView);
  const [loginMode, setLoginMode] = useState<LoginMode>("password");
  const [displayName, setDisplayName] = useState("");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [pinStatus, setPinStatus] = useState<CodeStatus>("idle");
  const [confirmStatus, setConfirmStatus] = useState<CodeStatus>("idle");
  /**
   * 注册的邮箱验证码：先点「发送验证码」，再把收到的六位数字填进来。
   * hint 里存的是开发/本机通道直接给出的那串码（填码时 clearError 会把
   * 账号 store 里的 devCode 抹掉，所以抄一份在自己手上）。
   */
  const [registerCode, setRegisterCode] = useState("");
  const [registerCodeStatus, setRegisterCodeStatus] = useState<CodeStatus>("idle");
  const [registerCodeSent, setRegisterCodeSent] = useState(false);
  const [registerHint, setRegisterHint] = useState<string | null>(null);
  const [resendIn, setResendIn] = useState(0);
  /**
   * 登录的邮箱验证码：跟注册一个路数，只是码的用途是「登录」。
   * loginHint 在发码那一刻把开发/本机通道的码抄一份在手上（输码时的
   * clearError 会把 store 里的 devCode 抹掉，抄下来才留得住）。
   */
  const [loginCode, setLoginCode] = useState("");
  const [loginCodeStatus, setLoginCodeStatus] = useState<CodeStatus>("idle");
  const [loginCodeSent, setLoginCodeSent] = useState(false);
  const [loginHint, setLoginHint] = useState<string | null>(null);
  const [loginResendIn, setLoginResendIn] = useState(0);
  const [localMessage, setLocalMessage] = useState<string | null>(null);

  const emailReady = isValidEmail(email);
  const passwordsMatch =
    password.length === 6 && password === confirmPassword;
  const codeReady = registerCode.length === 6;
  const registerReady =
    displayName.trim().length >= 2 &&
    emailReady &&
    codeReady &&
    isStrongPassword(password) &&
    passwordsMatch;
  const loginReady = emailReady && isStrongPassword(password);

  useEffect(() => {
    if (!open) return undefined;
    restoreFocusRef.current = document.activeElement as HTMLElement | null;
    const originalOverflow = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    setView(initialView);
    setLocalMessage(null);
    setLoginCode("");
    setLoginCodeStatus("idle");
    setLoginCodeSent(false);
    setLoginHint(null);
    setLoginResendIn(0);
    setRegisterCodeSent(false);
    setRegisterCode("");
    setRegisterHint(null);
    setResendIn(0);
    account.clearError();
    const focusTimer = window.setTimeout(
      () => emailRef.current?.focus(),
      80,
    );
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === "Escape") onCloseRef.current();
    };
    window.addEventListener("keydown", onKeyDown);
    return () => {
      window.clearTimeout(focusTimer);
      window.removeEventListener("keydown", onKeyDown);
      document.body.style.overflow = originalOverflow;
      restoreFocusRef.current?.focus();
    };
  }, [account.clearError, initialView, open]);

  // 发完码歇 60 秒再让重发（本机通道也一样，免得连点堆一串码）。
  // 注册和登录各有一支倒计时，共用这一枚秒针。
  useEffect(() => {
    if (resendIn <= 0 && loginResendIn <= 0) return undefined;
    const timer = window.setTimeout(() => {
      setResendIn((seconds) => Math.max(0, seconds - 1));
      setLoginResendIn((seconds) => Math.max(0, seconds - 1));
    }, 1000);
    return () => window.clearTimeout(timer);
  }, [resendIn, loginResendIn]);

  if (!open || typeof document === "undefined") return null;

  const flashStatus = (
    setter: (status: CodeStatus) => void,
    status: Exclude<CodeStatus, "idle">,
  ) => {
    setter(status);
    window.setTimeout(() => setter("idle"), status === "success" ? 700 : 950);
  };

  const switchView = (next: AuthView) => {
    setView(next);
    setLocalMessage(null);
    setPinStatus("idle");
    setConfirmStatus("idle");
    // 回注册页就是重新开始：上一个邮箱的验证码不作数。
    setRegisterCode("");
    setRegisterCodeStatus("idle");
    setRegisterCodeSent(false);
    setRegisterHint(null);
    setResendIn(0);
    account.clearError();
  };

  const switchLoginMode = (next: LoginMode) => {
    setLoginMode(next);
    setLoginCodeStatus("idle");
    setLocalMessage(null);
    account.clearError();
  };

  const submitPinLogin = async (submitted = password) => {
    if (!emailReady || !isStrongPassword(submitted) || account.busy) return;
    setPinStatus("idle");
    const succeeded = await account.signInWithPassword({
      email: normalizeEmail(email),
      password: submitted,
    });
    flashStatus(setPinStatus, succeeded ? "success" : "error");
    if (!succeeded) setPassword("");
  };

  const submitPasswordLogin = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    await submitPinLogin();
  };

  const sendRegisterCode = async () => {
    if (!emailReady || account.busy || resendIn > 0) return;
    const sent = await account.sendRegisterCode(normalizeEmail(email));
    if (!sent) return;
    // 码只回在开发/本机通道里：抄下来显示，输码时不会被 clearError 抹掉。
    setRegisterHint(useAccountStore.getState().devCode ?? null);
    setRegisterCode("");
    setRegisterCodeStatus("idle");
    setRegisterCodeSent(true);
    setResendIn(60);
  };

  const submitRegister = async (
    submittedPassword = password,
    submittedConfirm = confirmPassword,
  ) => {
    if (
      displayName.trim().length < 2 ||
      !emailReady ||
      !codeReady ||
      !isStrongPassword(submittedPassword) ||
      submittedConfirm !== submittedPassword ||
      account.busy
    ) {
      return;
    }
    setRegisterCodeStatus("idle");
    setPinStatus("idle");
    setConfirmStatus("idle");
    const succeeded = await account.registerWithPassword({
      displayName: displayName.trim(),
      email: normalizeEmail(email),
      password: submittedPassword,
      code: registerCode,
    });
    flashStatus(setPinStatus, succeeded ? "success" : "error");
    flashStatus(setConfirmStatus, succeeded ? "success" : "error");
    flashStatus(setRegisterCodeStatus, succeeded ? "success" : "error");
    if (!succeeded) {
      setPassword("");
      setConfirmPassword("");
      setRegisterCode("");
      return;
    }
    // 注册即登录：窗口收起来，人直接落到书架上。
    setLocalMessage("账号已就绪，正在打开书架……");
    window.setTimeout(() => {
      onClose();
      navigate("/shelf");
    }, 560);
  };

  const submitRegisterForm = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    await submitRegister(password, confirmPassword);
  };

  const sendLoginCode = async () => {
    if (!emailReady || account.busy || loginResendIn > 0) return;
    const sent = await account.sendLoginCode(normalizeEmail(email));
    if (!sent) return;
    // 跟注册一样：码只回在开发/本机通道里，抄下来显示。
    setLoginHint(useAccountStore.getState().devCode ?? null);
    setLoginCode("");
    setLoginCodeStatus("idle");
    setLoginCodeSent(true);
    setLoginResendIn(60);
  };

  const submitEmailCode = async (submitted = loginCode) => {
    if (!loginCodeSent || submitted.length !== 6 || account.busy) return;
    const succeeded = await account.signInWithEmailCode(
      normalizeEmail(email),
      submitted,
    );
    flashStatus(setLoginCodeStatus, succeeded ? "success" : "error");
    if (!succeeded) setLoginCode("");
  };

  const signOut = async () => {
    await account.signOut();
    onClose();
  };

  const accountPanel = account.user ? (
    <div className="auth-dialog__account-panel">
      <div className="auth-dialog__profile">
        <span className="auth-dialog__avatar" aria-hidden="true">
          {account.user.displayName.trim().slice(0, 1).toUpperCase() || "I"}
        </span>
        <span>
          <small>Signed in</small>
          <strong>{account.user.displayName}</strong>
          <em>{account.user.emailMasked ?? "Leafia Account"}</em>
        </span>
      </div>

      <div className="auth-dialog__account-facts">
        <p>
          <Mail size={15} aria-hidden="true" />
          <span>
            <small>邮箱</small>
            <strong>{account.user.emailMasked ?? "未绑定邮箱"}</strong>
          </span>
          {account.user.emailMasked ? (
            <Check size={15} aria-label="已绑定" />
          ) : null}
        </p>
      </div>

      {localMessage ? (
        <p className="auth-dialog__success" role="status">
          <Check size={14} aria-hidden="true" />
          {localMessage}
        </p>
      ) : null}

      <div className="auth-dialog__account-actions">
        <button type="button" className="is-quiet" onClick={onClose}>
          继续使用
        </button>
        <button
          type="button"
          className="is-danger"
          disabled={account.busy}
          onClick={() => void signOut()}
        >
          <LogOut size={15} aria-hidden="true" />
          退出登录
        </button>
      </div>
    </div>
  ) : null;

  const passwordLogin = (
    <form className="auth-dialog__form" onSubmit={submitPasswordLogin}>
      <label>
        <span>邮箱</span>
        <span className="auth-dialog__input">
          <FieldIcon>
            <Mail size={16} />
          </FieldIcon>
          <input
            ref={emailRef}
            type="email"
            autoComplete="email"
            placeholder="name@example.com"
            value={email}
            onChange={(event) => {
              setEmail(event.target.value);
              account.clearError();
            }}
          />
        </span>
      </label>
      <CodeField
        label="六位密码"
        value={password}
        status={pinStatus}
        disabled={account.busy}
        ariaLabel="六位数字密码"
        onChange={(next) => {
          setPassword(next);
          account.clearError();
        }}
        onComplete={(next) => void submitPinLogin(next)}
      />
      <small className="auth-dialog__rule">
        密码由 6 位数字组成。输入完成后自动登录。
      </small>
      <button
        type="submit"
        className="auth-dialog__submit"
        disabled={account.busy || !loginReady}
      >
        {account.busy ? (
          <LoaderCircle className="is-spinning" size={16} />
        ) : (
          <ArrowRight size={16} />
        )}
        登录
      </button>
    </form>
  );

  const emailCodeLogin = (
    <div className="auth-dialog__form">
      {!loginCodeSent ? (
        <label>
          <span>邮箱</span>
          <span className="auth-dialog__input">
            <FieldIcon>
              <Mail size={16} />
            </FieldIcon>
            <input
              ref={emailRef}
              type="email"
              autoComplete="email"
              maxLength={254}
              placeholder="name@example.com"
              value={email}
              onChange={(event) => {
                setEmail(event.target.value);
                setLoginCode("");
                setLoginHint(null);
                account.clearError();
              }}
            />
            <button
              type="button"
              disabled={account.busy || !emailReady || loginResendIn > 0}
              onClick={() => void sendLoginCode()}
            >
              {loginResendIn > 0 ? `${loginResendIn}s 后重发` : "获取验证码"}
            </button>
          </span>
        </label>
      ) : (
        <>
          <div className="auth-dialog__code-head">
            <button type="button" onClick={() => setLoginCodeSent(false)}>
              <ArrowLeft size={15} />
              返回邮箱
            </button>
            <span>{maskEmail(normalizeEmail(email))}</span>
          </div>
          <CodeField
            label="六位验证码"
            value={loginCode}
            status={loginCodeStatus}
            disabled={account.busy}
            autoFocus
            ariaLabel="邮箱登录验证码"
            onChange={(next) => {
              setLoginCode(next);
              account.clearError();
            }}
            onComplete={(next) => void submitEmailCode(next)}
          />
          {loginHint ? (
            <p className="auth-dialog__hint">
              当前环境未接通邮件，验证码直接显示：
              <strong>{loginHint}</strong>
            </p>
          ) : null}
          <div className="auth-dialog__code-actions">
            <button
              type="button"
              disabled={account.busy || loginResendIn > 0}
              onClick={() => void sendLoginCode()}
            >
              {loginResendIn > 0 ? `${loginResendIn}s 后重发` : "重新发送"}
            </button>
            <button
              type="button"
              className="auth-dialog__submit"
              disabled={account.busy || loginCode.length !== 6}
              onClick={() => void submitEmailCode()}
            >
              {account.busy ? (
                <LoaderCircle className="is-spinning" size={16} />
              ) : (
                <ArrowRight size={16} />
              )}
              登录
            </button>
          </div>
        </>
      )}
    </div>
  );

  const registerForm = (
    <form className="auth-dialog__form" onSubmit={submitRegisterForm}>
      <label>
        <span>昵称</span>
        <span className="auth-dialog__input">
          <FieldIcon>
            <UserRound size={16} />
          </FieldIcon>
          <input
            ref={emailRef}
            type="text"
            autoComplete="nickname"
            maxLength={24}
            placeholder="怎么称呼你"
            value={displayName}
            onChange={(event) => {
              setDisplayName(event.target.value);
              account.clearError();
            }}
          />
        </span>
      </label>
      <label>
        <span>邮箱</span>
        <span className="auth-dialog__input">
          <FieldIcon>
            <Mail size={16} />
          </FieldIcon>
          <input
            type="email"
            autoComplete="email"
            maxLength={254}
            placeholder="name@example.com"
            value={email}
            onChange={(event) => {
              setEmail(event.target.value);
              // 换了邮箱，上一个码就不作数了。
              setRegisterCode("");
              setRegisterCodeSent(false);
              setRegisterHint(null);
              setResendIn(0);
              account.clearError();
            }}
          />
          <button
            type="button"
            disabled={account.busy || !emailReady || resendIn > 0}
            onClick={() => void sendRegisterCode()}
          >
            {resendIn > 0
              ? `${resendIn}s 后重发`
              : registerCodeSent
                ? "重新发送"
                : "发送验证码"}
          </button>
        </span>
      </label>
      {/* 注册必须先过邮箱验证码这一关：没收到码就建不了号。 */}
      <CodeField
        label="邮箱验证码"
        value={registerCode}
        status={registerCodeStatus}
        disabled={account.busy || !registerCodeSent}
        ariaLabel="六位邮箱验证码"
        onChange={(next) => {
          setRegisterCode(next);
          account.clearError();
        }}
        onComplete={(next) => {
          if (
            password.length === 6 &&
            next === confirmPassword &&
            isStrongPassword(next)
          ) {
            void submitRegister(password, confirmPassword);
          }
        }}
      />
      {registerHint ? (
        <p className="auth-dialog__hint">
          当前环境未接通邮件，验证码直接显示：
          <strong>{registerHint}</strong>
        </p>
      ) : null}
      <CodeField
        label="六位密码"
        value={password}
        status={pinStatus}
        disabled={account.busy}
        ariaLabel="设置六位数字密码"
        onChange={(next) => {
          setPassword(next);
          account.clearError();
        }}
        onComplete={(next) => {
          // 最后一位按完就顺手提交，是老规矩；但确认密码这会儿多半还没填，
          // 没凑齐就不抢跑，等「创建账号」那颗按钮。
          if (confirmPassword.length === 6 && codeReady) {
            void submitRegister(next, confirmPassword);
          } else setPinStatus("success");
        }}
      />
      <CodeField
        label="确认密码"
        value={confirmPassword}
        status={confirmStatus}
        disabled={account.busy}
        ariaLabel="确认六位数字密码"
        onChange={(next) => {
          setConfirmPassword(next);
          account.clearError();
        }}
        onComplete={(next) => {
          if (password.length === 6 && next === password && codeReady) {
            void submitRegister(password, next);
          }
        }}
      />
      {confirmPassword && !passwordsMatch ? (
        <small className="auth-dialog__rule">两次输入的密码不一致</small>
      ) : null}
      <button
        type="submit"
        className="auth-dialog__submit"
        disabled={account.busy || !registerReady}
      >
        {account.busy ? (
          <LoaderCircle className="is-spinning" size={16} />
        ) : (
          <ArrowRight size={16} />
        )}
        创建账号
      </button>
    </form>
  );

  return createPortal(
    <div className="auth-dialog auth-dialog--fullscreen">
      <button
        type="button"
        className="auth-dialog__scrim"
        aria-label="关闭登录窗口"
        onClick={onClose}
      />
      <div className="auth-dialog__wash" aria-hidden="true">
        <span className="auth-dialog__note" data-note="0">
          ♪
        </span>
        <span className="auth-dialog__note" data-note="1">
          ♩
        </span>
        <span className="auth-dialog__note" data-note="2">
          ♫
        </span>
        <span className="auth-dialog__note" data-note="3">
          ♬
        </span>
      </div>
      <section
        className="auth-dialog__panel"
        role="dialog"
        aria-modal="true"
        aria-labelledby={titleId}
      >
        <button
          type="button"
          className="auth-dialog__close"
          aria-label="关闭"
          onClick={onClose}
        >
          <X size={18} />
        </button>

        <aside className="auth-dialog__aside">
          <div className="auth-dialog__brand">
            <img src="/leafia-mark.svg" alt="" />
            <span>
              <strong>Leafia</strong>
              <small>Moonlit knowledge space</small>
            </span>
          </div>
          <div className="auth-dialog__aside-copy">
            <span className="auth-dialog__eyebrow">Language in motion</span>
            <h2 id={titleId}>
              {accountPanel
                ? "账号空间"
                : view === "register"
                  ? "建立你的书架"
                  : "回到你的书架"}
            </h2>
            <p>
              {accountPanel
                ? "便条跟着账号走，换设备登录后仍会恢复。"
                : "从首页直接进入，不离开当前页面；关闭后回到原来的位置。"}
            </p>
          </div>
          <div className="auth-dialog__staff" aria-hidden="true">
            {Array.from({ length: 5 }, (_, index) => (
              <i key={index} />
            ))}
            <span>♪</span>
          </div>
        </aside>

        <div className="auth-dialog__main">
          {accountPanel ? (
            accountPanel
          ) : (
            <>
              <div className="auth-dialog__tabs" role="tablist">
                <button
                  type="button"
                  role="tab"
                  aria-selected={view === "signin"}
                  className={view === "signin" ? "is-active" : ""}
                  onClick={() => switchView("signin")}
                >
                  登录
                </button>
                <button
                  type="button"
                  role="tab"
                  aria-selected={view === "register"}
                  className={view === "register" ? "is-active" : ""}
                  onClick={() => switchView("register")}
                >
                  注册
                </button>
              </div>

              {view === "signin" ? (
                <>
                  <div className="auth-dialog__mode-switch">
                    <button
                      type="button"
                      className={loginMode === "password" ? "is-active" : ""}
                      onClick={() => switchLoginMode("password")}
                    >
                      密码登录
                    </button>
                    <button
                      type="button"
                      className={loginMode === "email" ? "is-active" : ""}
                      onClick={() => switchLoginMode("email")}
                    >
                      邮箱验证码
                    </button>
                  </div>
                  {loginMode === "password" ? passwordLogin : emailCodeLogin}
                </>
              ) : (
                registerForm
              )}

              {account.error ? (
                <p className="auth-dialog__error" role="alert">
                  {account.error}
                </p>
              ) : null}

              <p className="auth-dialog__switch-copy">
                {view === "signin" ? "还没有账号？" : "已经有账号？"}
                <button
                  type="button"
                  onClick={() =>
                    switchView(view === "signin" ? "register" : "signin")
                  }
                >
                  {view === "signin" ? "创建账号" : "返回登录"}
                </button>
              </p>
            </>
          )}
        </div>
      </section>
    </div>,
    document.body,
  );
}
