import {
  type CSSProperties,
  type MouseEvent as ReactMouseEvent,
  type ReactNode,
  useCallback,
  useEffect,
  useRef,
  useState,
} from "react";
import "./leafia-menu.css";

/** 面板的 id：顶栏那两颗按钮拿 aria-controls 指过来。 */
const PANEL_ID = "leafia-menu-panel";

/** 后面跟的色带最多几层 —— 再多就看不出是一叠纸了。 */
const MAX_LAYERS = 4;

export interface LeafiaMenuItem {
  label: string;
  ariaLabel: string;
  link: string;
  className?: string;
  disabled?: boolean;
  children?: LeafiaMenuItem[];
  /** 中文名，跟在英文名旁边（空间门上那行）。 */
  zh?: string;
  /** 这个空间里放什么，一行小字。 */
  caption?: string;
}

/** 槽位可以直接给节点，也可以给一个函数 —— 函数能拿到面板自己的 close。 */
export type MenuSlot =
  | ReactNode
  | ((panel: { close: () => void }) => ReactNode);

export interface LeafiaMenuProps {
  /** 目录内容。带 children 的成大组（空间铭牌 + 子项），不带的是一行普通链接。 */
  items?: LeafiaMenuItem[];
  /** 从哪一侧拉出来。 */
  position?: "left" | "right";
  /** 面板后面那几层色带，从前到后。给满三层会掐掉中间那层，免得色带糊成一条。 */
  colors?: string[];
  className?: string;
  logoUrl?: string;
  /** 面板里的强调色（--menu-accent）。 */
  accentColor?: string;
  /** 钉在视口上 —— 整站导航要这个，嵌在页面里就不要。 */
  isFixed?: boolean;
  /** 不另起一颗 MENU 按钮：让铭牌自己当入口，收起来的那颗按钮也就换成面板里的关闭键。 */
  hideToggle?: boolean;
  /** 外面拿它来开合面板：这个数一变就翻一次（开着就收，收着就开）。 */
  openSignal?: number;
  /** 外面让它先退下去 —— 跳走之后面板不该还挂在屏幕上。 */
  dismissed?: boolean;
  /** 点面板外面收起来。 */
  closeOnClickAway?: boolean;
  onMenuOpen?: () => void;
  onMenuClose?: () => void;
  onItemClick?: (item: LeafiaMenuItem, index: number) => void;
  /**
   * 排在目录下面。只在面板开着的时候挂上去：这种块多半自带一个动画循环，
   * 而收起来的面板是留在 DOM 里的，一直挂着就整场会话都在后台空转。
   */
  panelExtra?: MenuSlot;
  /** 排在目录上面，面板最顶上那一块。挂载规矩和 panelExtra 一样。 */
  panelTop?: MenuSlot;
}

/**
 * 一块从侧边拉出来的目录面板。
 *
 * 开合只有一个状态：root 上的 data-open。往哪走、走多快、谁先谁后，全写在
 * CSS 里（面板自己滑，行的标签一行比一行晚一点从行底顶上来），JS 只翻这个
 * 属性，不跑动画循环 —— 所以中断得掉、也拖不慢。
 *
 * 收着的时候面板只是被推到屏幕外，人眼看不见，但 Tab 还进得去，因此关着的
 * 面板挂 inert；顶栏本身不吃点击（pointer-events: none），只有里面的按钮吃。
 */
export function LeafiaMenu({
  items = [],
  position = "right",
  colors = [],
  className = "",
  logoUrl = "/leafia-mark.svg",
  accentColor,
  isFixed = false,
  hideToggle = false,
  openSignal = 0,
  dismissed = false,
  closeOnClickAway = true,
  onMenuOpen,
  onMenuClose,
  onItemClick,
  panelExtra,
  panelTop,
}: LeafiaMenuProps) {
  const [open, setOpen] = useState(false);
  /** 同一个值还留一份在手边：外面的事件回调里读到的 state 可能还是上一次渲染的。 */
  const openRef = useRef(false);
  const rootRef = useRef<HTMLDivElement | null>(null);
  const barRef = useRef<HTMLDivElement | null>(null);
  const panelRef = useRef<HTMLElement | null>(null);
  const signalRef = useRef(openSignal);

  const setMenu = useCallback(
    (next: boolean) => {
      if (openRef.current === next) return;
      openRef.current = next;
      setOpen(next);
      if (next) onMenuOpen?.();
      else onMenuClose?.();
    },
    [onMenuClose, onMenuOpen],
  );

  /** 开着就收，收着就开。 */
  const toggle = useCallback(() => setMenu(!openRef.current), [setMenu]);
  const close = useCallback(() => setMenu(false), [setMenu]);

  // 外面敲门（书房那颗铭牌派发 leafia:open-menu，转成 openSignal 递进来）。
  useEffect(() => {
    if (openSignal === signalRef.current) return;
    signalRef.current = openSignal;
    toggle();
  }, [openSignal, toggle]);

  useEffect(() => {
    if (!open) return;
    const onKey = (event: KeyboardEvent) => {
      if (event.key === "Escape") close();
    };
    document.addEventListener("keydown", onKey);
    return () => document.removeEventListener("keydown", onKey);
  }, [close, open]);

  useEffect(() => {
    if (!open || !closeOnClickAway) return;
    const onDown = (event: MouseEvent) => {
      const target = event.target as Node;
      if (panelRef.current?.contains(target)) return;
      /* 顶栏整条都算「自己人」：铭牌既是品牌也是开关，点它不该先收再开。
         顶栏本身 pointer-events: none，所以这儿只会命中它里面那颗真按钮。 */
      if (barRef.current?.contains(target)) return;
      close();
    };
    document.addEventListener("mousedown", onDown);
    return () => document.removeEventListener("mousedown", onDown);
  }, [close, closeOnClickAway, open]);

  const handleItemClick = (
    event: ReactMouseEvent<HTMLAnchorElement>,
    item: LeafiaMenuItem,
    index: number,
  ) => {
    // 站内的链接交给路由接手：不拦这一下，整页会从头载一遍。
    if (item.link.startsWith("/") && onItemClick) event.preventDefault();
    onItemClick?.(item, index);
    close();
  };

  /* 色带就是给过来的主题色：够三层就掐掉中间那层，不然两道颜色糊在一起。 */
  const rawLayers = colors.length ? colors.slice(0, MAX_LAYERS) : ["#1e1e22", "#35353c"];
  const layerColors =
    rawLayers.length >= 3
      ? rawLayers.filter((_, index) => index !== Math.floor(rawLayers.length / 2))
      : rawLayers;

  /* 行落位的次序：面板拉开之后，从上到下数着一行行顶上来（组名也算一行）。 */
  let step = 0;
  const nextStep = () => step++;

  const slot = (value: MenuSlot) =>
    typeof value === "function" ? value({ close }) : value;

  const rootStyle = {
    "--menu-layers": layerColors.length,
    ...(accentColor ? { "--menu-accent": accentColor } : {}),
  } as CSSProperties;

  return (
    <div
      ref={rootRef}
      className={["leafia-menu", isFixed && "leafia-menu--fixed", className]
        .filter(Boolean)
        .join(" ")}
      style={rootStyle}
      data-position={position}
      data-open={open || undefined}
      data-dismissed={dismissed || undefined}
    >
      <div className="leafia-menu__layers" aria-hidden="true">
        {layerColors.map((color, index) => (
          <span
            key={`${color}-${index}`}
            className="leafia-menu__layer"
            style={{ background: color, "--i": index } as CSSProperties}
          />
        ))}
      </div>

      <div ref={barRef} className="leafia-menu__bar">
        {hideToggle ? (
          /* 铭牌即入口：logo 自己就是开关，不再另起一颗 MENU 按钮。 */
          <button
            type="button"
            className="leafia-menu__mark leafia-menu__mark--trigger"
            aria-label="Leafia 功能菜单"
            aria-expanded={open}
            aria-controls={PANEL_ID}
            onClick={toggle}
          >
            <img
              src={logoUrl}
              alt="Leafia"
              className="leafia-menu__mark-img"
              draggable={false}
              width={110}
              height={24}
            />
          </button>
        ) : (
          <span className="leafia-menu__mark">
            <img
              src={logoUrl}
              alt="Leafia"
              className="leafia-menu__mark-img"
              draggable={false}
              width={110}
              height={24}
            />
          </span>
        )}

        {!hideToggle && (
          <button
            type="button"
            className="leafia-menu__toggle"
            aria-label={open ? "收起目录" : "打开目录"}
            aria-expanded={open}
            aria-controls={PANEL_ID}
            onClick={toggle}
          >
            <span className="leafia-menu__toggle-label" aria-hidden="true">
              {open ? "Close" : "Menu"}
            </span>
            <span className="leafia-menu__glyph" aria-hidden="true" />
          </button>
        )}
      </div>

      <nav
        id={PANEL_ID}
        ref={panelRef}
        className="leafia-menu__panel"
        aria-label="Leafia 目录"
        aria-hidden={!open}
        inert={!open || undefined}
      >
        {hideToggle && (
          <button
            type="button"
            className="leafia-menu__close"
            onClick={close}
            aria-label="收起目录"
          >
            <span aria-hidden="true" />
            <span aria-hidden="true" />
          </button>
        )}

        <div className="leafia-menu__scroll">
          {/* 顶上这块只在开着的时候挂（理由和下面 panelExtra 一样）。 */}
          {open ? slot(panelTop) : null}

          <ul className="leafia-menu__list" role="list">
            {items.length === 0 ? (
              <li className="leafia-menu__row" aria-hidden="true">
                <span className="leafia-menu__link">
                  <span className="leafia-menu__label">No items</span>
                </span>
              </li>
            ) : (
              items.map((item, index) =>
                item.children?.length ? (
                  <li
                    className="leafia-menu__row leafia-menu__row--group"
                    key={`${item.label}-${index}`}
                  >
                    <span
                      className="leafia-menu__group"
                      data-index={index + 1}
                      style={{ "--i": nextStep() } as CSSProperties}
                    >
                      {item.label}
                      {item.zh ? (
                        <small className="leafia-menu__group-zh">{item.zh}</small>
                      ) : null}
                    </span>
                    {item.caption ? (
                      <span className="leafia-menu__group-caption">{item.caption}</span>
                    ) : null}
                    <ul className="leafia-menu__sub" role="list">
                      {item.children.map((child) =>
                        child.disabled ? (
                          <li key={child.label}>
                            <span
                              className={[
                                "leafia-menu__link",
                                "leafia-menu__link--sub",
                                "leafia-menu__link--off",
                                child.className,
                              ]
                                .filter(Boolean)
                                .join(" ")}
                              aria-label={child.ariaLabel}
                              aria-disabled="true"
                            >
                              <span
                                className="leafia-menu__label"
                                style={{ "--i": nextStep() } as CSSProperties}
                              >
                                {child.label}
                              </span>
                            </span>
                          </li>
                        ) : (
                          <li key={child.label}>
                            <a
                              className={[
                                "leafia-menu__link",
                                "leafia-menu__link--sub",
                                child.className,
                              ]
                                .filter(Boolean)
                                .join(" ")}
                              href={child.link}
                              aria-label={child.ariaLabel}
                              onClick={(event) => handleItemClick(event, child, index)}
                            >
                              <span
                                className="leafia-menu__label"
                                style={{ "--i": nextStep() } as CSSProperties}
                              >
                                {child.label}
                              </span>
                            </a>
                          </li>
                        ),
                      )}
                    </ul>
                  </li>
                ) : item.disabled ? (
                  <li className="leafia-menu__row" key={`${item.label}-${index}`}>
                    <span
                      className={["leafia-menu__link", "leafia-menu__link--off", item.className]
                        .filter(Boolean)
                        .join(" ")}
                      aria-label={item.ariaLabel}
                      aria-disabled="true"
                    >
                      <span
                        className="leafia-menu__label"
                        style={{ "--i": nextStep() } as CSSProperties}
                      >
                        {item.label}
                      </span>
                    </span>
                  </li>
                ) : (
                  <li className="leafia-menu__row" key={`${item.label}-${index}`}>
                    <a
                      className={["leafia-menu__link", item.className]
                        .filter(Boolean)
                        .join(" ")}
                      href={item.link}
                      aria-label={item.ariaLabel}
                      onClick={(event) => handleItemClick(event, item, index)}
                    >
                      <span
                        className="leafia-menu__label"
                        style={{ "--i": nextStep() } as CSSProperties}
                      >
                        {item.label}
                      </span>
                    </a>
                  </li>
                ),
              )
            )}
          </ul>

          {open ? slot(panelExtra) : null}
        </div>
      </nav>
    </div>
  );
}

export default LeafiaMenu;
