/**
 * 六格验证码 / 六位密码（PasscodeField）
 *
 * 一格一个数字，凑满就报一声「好了」。上面那六格是画给人看的（aria-hidden），
 * 底下压着一个真的 <input>：手机键盘、短信验证码自动填充、读屏器、外接键盘
 * 全靠它，六格只是它的表情。
 *
 * 三件事的节拍：
 *   · 落格 —— 数字从下面浮上来（挂载动画），一次落好几个就一个一个错开；
 *   · 沉格 —— 退格、外面的清空、报错倒着清，数字都往下沉出去，格底褪回浅色；
 *   · 通过 —— 一层色片从中间往两边抹开盖住六格，勾自己一笔描出来。
 *
 * 跟原先那套的分别：
 *   · 不带动画引擎（弹簧值那套）也不领图标库的情：落格/沉格是 CSS 动画，
 *     错峰靠 animation-delay，滑块走 transform 过渡，勾是自画的 SVG；
 *   · 六格宽度是流动的 —— 容器窄了自己缩，不靠量像素算格子位置；
 *   · 报错清空、通过盖色这些收尾都留了减少动效的走法（不动，但结果一样）。
 */
import {
  useEffect,
  useId,
  useLayoutEffect,
  useRef,
  useState,
  type CSSProperties,
  type ChangeEvent,
  type ClipboardEvent,
  type KeyboardEvent,
  type MouseEvent as ReactMouseEvent,
} from "react";
import { cn } from "../../lib/cn";
import "./passcode-field.css";

export type PasscodeStatus = "idle" | "error" | "success";

export interface PasscodeTone {
  /** 空格子的底色。 */
  plate: string;
  /** 数字的颜色。 */
  digit: string;
  /** 填进数字后格底的颜色。 */
  accent: string;
  /** 光标和悬停用的墨色。 */
  ink: string;
  /** 报错时的红。 */
  danger: string;
}

export interface PasscodeFieldProps {
  /** 几格。默认 6。 */
  length?: number;
  /** 受控值：只认数字，多出来的截掉。不传就是自己管自己（配 defaultValue）。 */
  value?: string;
  defaultValue?: string;
  /** 每变一次都报一声（清空会报空串）。 */
  onChange?: (next: string) => void;
  /** 从「没满」跨到「满了」的那一下报一次，不重复报。 */
  onComplete?: (code: string) => void;
  status?: PasscodeStatus;
  /** 把数字盖成圆点（密码那种）。 */
  mask?: boolean;
  disabled?: boolean;
  autoFocus?: boolean;
  /** 给读屏器的名字，比如「六位手机验证码」。 */
  label: string;
  /** 五层颜色，缺的走默认（叶子紫那一套）。 */
  tone?: Partial<PasscodeTone>;
  /** 一格最宽多少像素 —— 容器窄了会自己缩。 */
  size?: number;
  gap?: number;
  radius?: number;
  className?: string;
}

/** 一次落进来好几个数字时，彼此错开这么多毫秒。 */
const CASCADE_MS = 26;
/** 报错倒着清的时候，一格和下一格之间隔多久。 */
const DRAIN_STEP_MS = 40;
/** 一个数字沉下去走多久 —— 沉完这么久就把那笔账撤掉。 */
const EXIT_MS = 220;

const DEFAULT_TONE: PasscodeTone = {
  plate: "#e8e3f1",
  digit: "#342c36",
  accent: "#8f7fc0",
  ink: "#51466f",
  danger: "#a25151",
};

/** 勾的形状：一条两折的线，配 pathLength=1 好一笔描出来。 */
const TICK_PATH = "M5.6 12.4 10.1 17 18.6 7.6";

const digitsOf = (raw: string) => raw.replace(/\D/g, "");

const toSlots = (raw: string, length: number) => {
  const digits = digitsOf(raw ?? "").slice(0, length);
  return Array.from({ length }, (_, index) => digits[index] ?? "");
};

const firstEmptyOf = (slots: string[]) => {
  const index = slots.indexOf("");
  return index === -1 ? slots.length - 1 : index;
};

const isFull = (slots: string[]) => slots.every(Boolean);

/** 正在往下沉的那一笔：谁、延迟多少、第几号（好让同一格连着沉两次也分得开）。 */
interface Leaving {
  char: string;
  delay: number;
  token: number;
}

export function PasscodeField({
  length = 6,
  value,
  defaultValue = "",
  onChange,
  onComplete,
  status = "idle",
  mask = false,
  disabled = false,
  autoFocus = false,
  label,
  tone,
  size = 56,
  gap = 8,
  radius = 12,
  className,
}: PasscodeFieldProps) {
  const describedById = useId();
  const rowRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);
  const [inner, setInner] = useState(() => digitsOf(defaultValue).slice(0, length));
  const [active, setActive] = useState(() =>
    firstEmptyOf(toSlots(value ?? defaultValue, length)),
  );
  const [focused, setFocused] = useState(false);
  const [leaving, setLeaving] = useState<Record<number, Leaving>>({});
  const [draining, setDraining] = useState(false);
  const [caretX, setCaretX] = useState(0);

  const controlled = value !== undefined;
  const code = (controlled ? digitsOf(value) : inner).slice(0, length);
  const slots = toSlots(code, length);
  const filledCount = slots.filter(Boolean).length;
  const busy = disabled || draining || status === "success";

  /* 这几个 ref 让回调随时读得到最新的账，又不用把它们拖进依赖数组。 */
  const slotsRef = useRef(slots);
  slotsRef.current = slots;
  const leavingRef = useRef(leaving);
  leavingRef.current = leaving;
  const timerRef = useRef<number[]>([]);
  const tokenRef = useRef(0);
  /** 我们自己写下去的那串码 —— 外面换了值才看得出来（那才需要补动画）。 */
  const committedRef = useRef(code);
  /** 落格错峰：谁排第几个。挂载动画开始前就得写好，所以只能在动作里记。 */
  const landDelayRef = useRef<Record<number, number>>({});
  const onChangeRef = useRef(onChange);
  onChangeRef.current = onChange;
  const onCompleteRef = useRef(onComplete);
  onCompleteRef.current = onComplete;

  useEffect(
    () => () => {
      timerRef.current.forEach((timer) => window.clearTimeout(timer));
      timerRef.current = [];
    },
    [],
  );

  /** 记一笔「往下沉」，到点自己撤。 */
  const pushLeave = (index: number, char: string, delay: number) => {
    if (leavingRef.current[index]) return;
    tokenRef.current += 1;
    const token = tokenRef.current;
    setLeaving((map) => ({ ...map, [index]: { char, delay, token } }));
    const timer = window.setTimeout(() => {
      setLeaving((map) => {
        if (map[index]?.token !== token) return map;
        const next = { ...map };
        delete next[index];
        return next;
      });
    }, delay + EXIT_MS);
    timerRef.current.push(timer);
  };

  /** 认下一串新的码：自己管就写进自己，报了人就不重复报。 */
  const commit = (next: string[], wasFull: boolean) => {
    const nextCode = next.join("");
    if (nextCode === slotsRef.current.join("")) return;
    committedRef.current = nextCode;
    if (!controlled) setInner(nextCode);
    onChangeRef.current?.(nextCode);
    if (!wasFull && isFull(next)) onCompleteRef.current?.(nextCode);
  };

  const insert = (raw: string, from = active) => {
    const digits = digitsOf(raw);
    if (!digits || busy) return;
    const next = slotsRef.current.slice();
    const wasFull = isFull(next);
    let cursor = from;
    let order = 0;
    for (const char of digits) {
      if (cursor >= length) break;
      next[cursor] = char;
      landDelayRef.current[cursor] = order * CASCADE_MS;
      order += 1;
      cursor += 1;
    }
    if (!order) return;
    commit(next, wasFull);
    setActive(firstEmptyOf(next));
  };

  const clearSlot = (index: number, stepBack = false) => {
    const char = slotsRef.current[index];
    if (!char) {
      if (stepBack) setActive(index);
      return;
    }
    pushLeave(index, char, 0);
    const next = slotsRef.current.slice();
    next[index] = "";
    commit(next, true);
    if (stepBack) setActive(index);
  };

  /* 外面把值换了（清空、灌码、换长度）：少掉的那几格补上「沉下去」，光标挪回第一个空格。 */
  useLayoutEffect(() => {
    if (code === committedRef.current) return;
    const before = toSlots(committedRef.current, length);
    committedRef.current = code;
    let order = 0;
    slots.forEach((char, index) => {
      const was = before[index];
      if (char || !was) return;
      pushLeave(index, was, order * CASCADE_MS);
      order += 1;
    });
    setActive(firstEmptyOf(slots));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [code, length]);

  useEffect(() => {
    setActive(firstEmptyOf(slotsRef.current));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [length]);

  /* 报错：从最后一格往回，一格一格沉，沉完了再把值清空（那一下会报 onChange）。 */
  useEffect(() => {
    if (status !== "error") return undefined;
    const filled = slotsRef.current
      .map((char, index) => (char ? index : -1))
      .filter((index) => index >= 0)
      .reverse();
    if (!filled.length) return undefined;
    setDraining(true);
    filled.forEach((index, order) => {
      const char = slotsRef.current[index];
      if (char) pushLeave(index, char, order * DRAIN_STEP_MS);
    });
    const life = (filled.length - 1) * DRAIN_STEP_MS + EXIT_MS;
    const timer = window.setTimeout(() => {
      setDraining(false);
      commit(Array.from({ length }, () => ""), true);
      setActive(0);
    }, life);
    timerRef.current.push(timer);
    return () => {
      window.clearTimeout(timer);
      setDraining(false);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [status, length]);

  useEffect(() => {
    if (autoFocus) inputRef.current?.focus();
  }, [autoFocus]);

  /* 光标停在哪一格：量那一格的中心。容器一变宽就重量（六格是流动的）。 */
  useLayoutEffect(() => {
    const row = rowRef.current;
    if (!row) return undefined;
    const measure = () => {
      const nodes = row.querySelectorAll<HTMLElement>(".passcode-field__slot");
      const slot = nodes[Math.min(active, nodes.length - 1)];
      setCaretX(slot ? slot.offsetLeft + slot.offsetWidth / 2 : 0);
    };
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(row);
    return () => observer.disconnect();
  }, [active, code, length]);

  const onKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
    if (busy || event.metaKey || event.ctrlKey || event.altKey) return;
    const key = event.key;
    if (/^[0-9]$/.test(key)) {
      event.preventDefault();
      insert(key);
      return;
    }
    if (key === "Backspace") {
      event.preventDefault();
      if (slots[active]) clearSlot(active);
      else if (active > 0) clearSlot(active - 1, true);
      return;
    }
    if (key === "Delete") {
      event.preventDefault();
      clearSlot(active);
      return;
    }
    if (key === "ArrowLeft") {
      event.preventDefault();
      setActive(Math.max(active - 1, 0));
      return;
    }
    if (key === "ArrowRight") {
      event.preventDefault();
      setActive(Math.min(active + 1, length - 1));
      return;
    }
    if (key === "Home") {
      event.preventDefault();
      setActive(0);
      return;
    }
    if (key === "End") {
      event.preventDefault();
      setActive(length - 1);
    }
  };

  const onPaste = (event: ClipboardEvent<HTMLInputElement>) => {
    if (busy) return;
    event.preventDefault();
    insert(event.clipboardData.getData("text"));
  };

  /* 手机键盘、输入法这些不一定走 keydown，落到 input 事件上的数字接着填。 */
  const onInput = (event: ChangeEvent<HTMLInputElement>) => {
    if (busy) return;
    const digits = digitsOf(event.target.value);
    if (!digits) return;
    insert(digits, digits.length === 1 ? active : 0);
  };

  const onRowMouseDown = (event: ReactMouseEvent<HTMLDivElement>) => {
    if (!disabled) {
      event.preventDefault();
      const row = rowRef.current;
      const nodes = row ? [...row.querySelectorAll<HTMLElement>(".passcode-field__slot")] : [];
      const hit = nodes.findIndex((node) => {
        const rect = node.getBoundingClientRect();
        return event.clientX >= rect.left && event.clientX <= rect.right;
      });
      if (hit >= 0) setActive(Math.min(hit, firstEmptyOf(slotsRef.current)));
    }
    if (!busy) inputRef.current?.focus();
  };

  const showCaret =
    focused &&
    !disabled &&
    status !== "success" &&
    (status === "error" || !slots[active]);

  const colors = { ...DEFAULT_TONE, ...tone };

  return (
    <div
      className={cn("passcode-field", className)}
      style={
        {
          "--pf-n": length,
          "--pf-size": `${size}px`,
          "--pf-gap": `${gap}px`,
          "--pf-radius": `${radius}px`,
          "--pf-plate": colors.plate,
          "--pf-digit": colors.digit,
          "--pf-accent": colors.accent,
          "--pf-ink": colors.ink,
          "--pf-danger": colors.danger,
          "--pf-tick": `${Math.round(Math.min(size, 56) * 0.52)}px`,
        } as CSSProperties
      }
    >
      <div
        ref={rowRef}
        className="passcode-field__row"
        data-status={status}
        data-draining={draining ? "" : undefined}
        data-focused={focused ? "" : undefined}
        data-disabled={disabled ? "" : undefined}
        onMouseDown={onRowMouseDown}
      >
        <input
          ref={inputRef}
          className="passcode-field__input"
          type="text"
          inputMode="numeric"
          autoComplete="one-time-code"
          pattern="[0-9]*"
          maxLength={length}
          value=""
          aria-label={label}
          aria-invalid={status === "error"}
          aria-describedby={describedById}
          disabled={disabled}
          readOnly={status === "success"}
          onKeyDown={onKeyDown}
          onPaste={onPaste}
          onChange={onInput}
          onFocus={() => setFocused(true)}
          onBlur={() => setFocused(false)}
        />
        {slots.map((char, index) => {
          const leavingSlot = leaving[index];
          return (
            <span
              key={index}
              className="passcode-field__slot"
              data-filled={!leavingSlot && char ? "" : undefined}
              data-active={focused && index === active ? "" : undefined}
              aria-hidden="true"
            >
              {leavingSlot ? (
                <span
                  key={`leave:${index}:${leavingSlot.token}`}
                  className="passcode-field__digit is-leaving"
                  style={{ "--pf-delay": `${leavingSlot.delay}ms` } as CSSProperties}
                >
                  {mask ? "•" : leavingSlot.char}
                </span>
              ) : char ? (
                <span
                  key={`digit:${index}:${char}`}
                  className="passcode-field__digit"
                  style={
                    { "--pf-delay": `${landDelayRef.current[index] ?? 0}ms` } as CSSProperties
                  }
                >
                  {mask ? "•" : char}
                </span>
              ) : null}
            </span>
          );
        })}
        <span
          className="passcode-field__caret"
          data-show={showCaret ? "" : undefined}
          style={{ transform: `translateX(${caretX}px)` }}
          aria-hidden="true"
        />
        <span className="passcode-field__wash" aria-hidden="true">
          <svg className="passcode-field__tick" viewBox="0 0 24 24" fill="none">
            <path
              d={TICK_PATH}
              pathLength={1}
              stroke="currentColor"
              strokeWidth={2.2}
              strokeLinecap="round"
              strokeLinejoin="round"
            />
          </svg>
        </span>
      </div>
      <span id={describedById} className="passcode-field__sr" aria-live="polite">
        {status === "success" ? "验证码已通过" : `已输入 ${filledCount} / ${length} 位`}
      </span>
    </div>
  );
}

export default PasscodeField;
