/**
 * 一个词的原形候选：reported → report、studies → study、running → run …
 *
 * 词典里常只有原形词条，书里却是 reported / studies / bigger 这样的变形。
 * 查不到原词时拿这些候选再查一遍，卡片上就能给出「原形 + 意思」。
 * 规则是够用就好的那套：常见后缀 + 一张高频不规则表；宁多试几个，别漏。
 */
export function lemmaCandidates(term: string): string[] {
  const word = term.trim().toLowerCase();
  if (!/^[a-z][a-z'-]*$/.test(word) || word.length < 3) return [];

  const out: string[] = [];
  const push = (candidate: string | undefined) => {
    if (!candidate || candidate.length < 2 || candidate === word) return;
    if (!out.includes(candidate)) out.push(candidate);
  };
  // 末尾是双写辅音（stopp / runn / bigg）：去掉一个再当候选。
  const undouble = (stem: string) =>
    /([bdfglmnprstz])\1$/.test(stem) ? stem.slice(0, -1) : undefined;

  // 高频不规则形。不求全：查不到还有后缀规则兜着。
  const irregular: Record<string, string> = {
    am: "be", is: "be", are: "be", was: "be", were: "be", been: "be", being: "be",
    has: "have", had: "have", having: "have",
    does: "do", did: "do", done: "do", doing: "do",
    goes: "go", went: "go", gone: "go",
    made: "make", took: "take", taken: "take", gave: "give", given: "give",
    got: "get", gotten: "get", came: "come", saw: "see", seen: "see",
    said: "say", knew: "know", known: "know", thought: "think", found: "find",
    ran: "run", brought: "bring", bought: "buy", taught: "teach", caught: "catch",
    left: "leave", felt: "feel", kept: "keep", held: "hold", told: "tell",
    wrote: "write", written: "write", spoke: "speak", spoken: "speak",
    broke: "break", broken: "break", chose: "choose", chosen: "choose",
    began: "begin", begun: "begin", lost: "lose", meant: "mean", met: "meet",
    paid: "pay", sent: "send", sat: "sit", slept: "sleep", spent: "spend",
    stood: "stand", won: "win", wore: "wear", worn: "wear",
    better: "good", best: "good", worse: "bad", worst: "bad",
    children: "child", men: "man", women: "woman", teeth: "tooth",
    feet: "foot", mice: "mouse", geese: "goose",
    lives: "life", wives: "wife", knives: "knife", leaves: "leaf",
  };
  push(irregular[word]);

  if (word.endsWith("ies") || word.endsWith("ied")) push(`${word.slice(0, -3)}y`);
  // 顺序按「像不像真的」排：-ed / -ing 的正主多是光秃秃的词干（walked → walk），
  // 其次是去双写（running → run），最后才轮到补个 e（making → make）。
  if (word.endsWith("ing")) {
    const stem = word.slice(0, -3);
    push(stem);
    push(undouble(stem));
    push(`${stem}e`);
  }
  if (word.endsWith("ed")) {
    const stem = word.slice(0, -2);
    push(stem);
    push(undouble(stem));
    push(`${stem.slice(0, -1)}e`);
  }
  if (word.endsWith("es") || (word.endsWith("s") && !word.endsWith("ss"))) {
    push(word.slice(0, -1));
    if (word.endsWith("es")) push(word.slice(0, -2));
  }
  if (word.endsWith("est")) {
    const stem = word.slice(0, -3);
    push(stem);
    push(undouble(stem));
    push(`${stem}e`);
  }
  if (word.endsWith("er")) {
    const stem = word.slice(0, -2);
    push(stem);
    push(undouble(stem));
    push(`${stem}e`);
  }
  if (word.endsWith("ly")) {
    const stem = word.slice(0, -2);
    push(stem);
    push(`${stem}e`);
  }
  return out;
}

