/**
 * 全局账号态。主题控制、设置面板和抽屉同步共用同一份会话，避免各自
 * 调用 Hook 后得到互不相干的登录状态。
 */
import { create } from "zustand";
import type { AuthUser, ThemeId } from "@leafia/shared";
import {
  ApiError,
  fetchAccount,
  loginWithPassword,
  loginDeveloper,
  registerWithPassword,
  requestEmailLoginCode,
  requestRegisterCode,
  signOutRemote,
  updateRemoteTheme,
  verifyEmailLoginCode,
} from "./accountApi";
import {
  consumeLocalLoginCode,
  consumeLocalRegisterCode,
  createLocalAccount,
  findLocalAccount,
  issueLocalLoginCode,
  issueLocalRegisterCode,
  maskEmail,
  verifyLocalAccount,
} from "./localAccount";
import { loadThemeId } from "../store/theme";

const SESSION_STORAGE_KEY = "leafia:account:v1";

export interface StoredSession {
  accessToken: string;
  refreshToken: string;
  expiresAt: string;
  user: AuthUser;
  /** 本机账号：这台设备上注册的，没有后端可同步。 */
  local?: boolean;
}

/**
 * 服务器到底在不在？404 / 405、说不清原因的 5xx、连不上，都算「不在」——
 * 静态站点后面没有 Fastify，注册请求就是这么折的。
 * 服务器答了话、还把原因写清楚了（带了 error 码）的不算：比如「邮件通道没配」
 * 是个 503，但那是真服务器在报事，这时不能再悄悄退回本机账号。
 */
function serverAbsent(error: unknown) {
  if (error instanceof ApiError) {
    if (error.status === 404 || error.status === 405 || error.status === 0) {
      return true;
    }
    if (error.status >= 500) return !error.code;
    return false;
  }
  return true;
}

function localSession(account: {
  id: string;
  displayName: string;
  email: string;
}): StoredSession {
  return {
    accessToken: `local:${account.id}`,
    refreshToken: "",
    expiresAt: "",
    local: true,
    user: {
      id: account.id,
      displayName: account.displayName,
      emailMasked: maskEmail(account.email),
      wechatBound: false,
      themeId: loadThemeId(),
    },
  };
}

export type AccountStatus = "anonymous" | "signed-in";

function normalizeSession(value: unknown): StoredSession | null {
  if (!value || typeof value !== "object") return null;
  const candidate = value as Partial<StoredSession>;
  if (
    typeof candidate.accessToken !== "string" ||
    !candidate.accessToken ||
    !candidate.user ||
    typeof candidate.user.id !== "string"
  ) {
    return null;
  }
  return {
    accessToken: candidate.accessToken,
    refreshToken:
      typeof candidate.refreshToken === "string" ? candidate.refreshToken : "",
    expiresAt:
      typeof candidate.expiresAt === "string" ? candidate.expiresAt : "",
    user: {
      ...candidate.user,
      // 早先版本存下来的会话可能缺 displayName：账号页一渲染就
      // `.trim()` 崩掉（点铭牌进来的「用户界面」正是那一页）。名字
      // 补一个能用的，别让人卡在白屏上。
      displayName:
        typeof candidate.user.displayName === "string" &&
        candidate.user.displayName.trim()
          ? candidate.user.displayName
          : "读者",
    },
    ...(candidate.local ? { local: true } : {}),
  };
}

export function loadStoredSession(): StoredSession | null {
  if (typeof localStorage === "undefined") return null;
  try {
    return normalizeSession(
      JSON.parse(localStorage.getItem(SESSION_STORAGE_KEY) ?? "null"),
    );
  } catch {
    return null;
  }
}

function persistSession(session: StoredSession | null) {
  if (typeof localStorage === "undefined") return;
  try {
    if (session) {
      localStorage.setItem(SESSION_STORAGE_KEY, JSON.stringify(session));
    } else {
      localStorage.removeItem(SESSION_STORAGE_KEY);
    }
  } catch {
    // 隐私模式：登录仍有效，只是刷新后需要重新登录。
  }
}

function describeError(error: unknown) {
  if (error instanceof ApiError) {
    if (error.code === "invalid_credentials") return "邮箱或密码不正确。";
    if (error.code === "email_registered") return "这个邮箱已经注册过了。";
    if (error.code === "email_not_registered") {
      return "这个邮箱还没有注册，先去注册一个。";
    }
    if (error.code === "mail_not_configured") {
      return "邮件通道尚未配置，注册验证码暂时发不出去。";
    }
    if (error.code === "mail_send_failed") {
      return "验证码发送失败，请稍后重试。";
    }
    if (error.code === "invalid_email") return "邮箱格式不正确，请检查后重试。";
    if (error.code === "code_expired") return "验证码已过期，请重新获取。";
    if (error.code === "invalid_code") return "验证码不正确，请检查后重试。";
    if (error.status === 401) return "登录已过期，请重新登录。";
    if (error.status === 400) return "请检查填写内容后重试。";
    return error.message;
  }
  return "连接不到服务器，便条先存在本机，联网后再登录即可同步。";
}

interface AccountState {
  session: StoredSession | null;
  bootstrapped: boolean;
  busy: boolean;
  error: string | null;
  devCode: string | null;
  bootstrap: () => Promise<void>;
  signInWithDeveloper: () => Promise<boolean>;
  /** 注册第一步：把验证码发到邮箱；静态站点没人发信，码就地在本地生成。 */
  sendRegisterCode: (email: string) => Promise<boolean>;
  registerWithPassword: (input: {
    displayName: string;
    email: string;
    password: string;
    code: string;
  }) => Promise<boolean>;
  signInWithPassword: (input: {
    email: string;
    password: string;
  }) => Promise<boolean>;
  /** 登录第一步：把邮箱验证码发出去；静态站点没人发信，码就地在本地生成。 */
  sendLoginCode: (email: string) => Promise<boolean>;
  signInWithEmailCode: (email: string, code: string) => Promise<boolean>;
  signOut: () => Promise<void>;
  clearError: () => void;
  setUserTheme: (themeId: ThemeId) => void;
}

export const useAccountStore = create<AccountState>((set, get) => ({
  session: loadStoredSession(),
  bootstrapped: false,
  busy: false,
  error: null,
  devCode: null,

  async bootstrap() {
    if (get().bootstrapped) return;
    const stored = loadStoredSession();
    const token = stored?.accessToken;
    if (!token) {
      set({ bootstrapped: true });
      return;
    }
    // 本机账号没有远端可问，直接用本地那份。
    if (stored?.local) {
      set({ bootstrapped: true });
      return;
    }
    try {
      const payload = await fetchAccount(token);
      set((state) => {
        if (!state.session || state.session.accessToken !== token) {
          return { bootstrapped: true };
        }
        const session = { ...state.session, user: payload.user };
        persistSession(session);
        return { session, bootstrapped: true };
      });
    } catch (caught) {
      if (caught instanceof ApiError && caught.status === 401) {
        persistSession(null);
        set({
          session: null,
          bootstrapped: true,
          error: "登录已过期，请重新登录。",
        });
        return;
      }
      set({ bootstrapped: true });
    }
  },

  async signInWithDeveloper() {
    set({ busy: true, error: null });
    try {
      const payload = await loginDeveloper();
      persistSession(payload);
      set({ session: payload, error: null, devCode: null });
      return true;
    } catch (caught) {
      set({ error: describeError(caught) });
      return false;
    } finally {
      set({ busy: false });
    }
  },

  async sendRegisterCode(email) {
    set({ busy: true, error: null });
    try {
      const result = await requestRegisterCode(email);
      set({ devCode: result.devCode ?? null });
      return true;
    } catch (caught) {
      // 后端不在（静态站点）：码在本地生成，照样要过这一关再建号。
      if (serverAbsent(caught)) {
        if (findLocalAccount(email)) {
          set({ error: "这个邮箱已经在本机注册过了，直接登录吧。" });
          return false;
        }
        set({ devCode: issueLocalRegisterCode(email) });
        return true;
      }
      set({ error: describeError(caught) });
      return false;
    } finally {
      set({ busy: false });
    }
  },

  async registerWithPassword(input) {
    set({ busy: true, error: null });
    try {
      const payload = await registerWithPassword(input);
      persistSession(payload);
      set({ session: payload, error: null, devCode: null });
      return true;
    } catch (caught) {
      // 后端不在（静态站点）：账号落在本机，注册照样能走完 —— 但验证码
      // 这一关一样要过，码是本地发的，对不上就不建号。
      if (serverAbsent(caught)) {
        const verdict = consumeLocalRegisterCode(input.email, input.code);
        if (verdict !== "ok") {
          set({
            error:
              verdict === "expired"
                ? "验证码已过期，请重新获取。"
                : "验证码不正确，请检查后重试。",
          });
          return false;
        }
        const created = createLocalAccount(input);
        if (!created.ok) {
          set({ error: "这个邮箱已经在本机注册过了，直接登录吧。" });
          return false;
        }
        const session = localSession(created.account);
        persistSession(session);
        set({ session, error: null, devCode: null });
        return true;
      }
      set({ error: describeError(caught) });
      return false;
    } finally {
      set({ busy: false });
    }
  },

  async signInWithPassword(input) {
    set({ busy: true, error: null });
    try {
      const payload = await loginWithPassword(input);
      persistSession(payload);
      set({ session: payload, error: null, devCode: null });
      return true;
    } catch (caught) {
      if (serverAbsent(caught)) {
        const account = verifyLocalAccount(input);
        if (!account) {
          set({
            error: findLocalAccount(input.email)
              ? "邮箱或密码不正确。"
              : "这台设备上还没有这个账号，先注册一个。",
          });
          return false;
        }
        const session = localSession(account);
        persistSession(session);
        set({ session, error: null, devCode: null });
        return true;
      }
      set({ error: describeError(caught) });
      return false;
    } finally {
      set({ busy: false });
    }
  },

  async sendLoginCode(email) {
    set({ busy: true, error: null });
    try {
      const result = await requestEmailLoginCode(email);
      set({ devCode: result.devCode ?? null });
      return true;
    } catch (caught) {
      // 静态站点（没有后端发信，也没有后端校验）：只有这台设备上已经注册过
      // 的邮箱才谈得上「用验证码登录」——码在本地生成，摆在界面上让人抄。
      if (serverAbsent(caught)) {
        if (!findLocalAccount(email)) {
          set({ error: "这台设备上还没有这个邮箱的账号，先注册一个。" });
          return false;
        }
        set({ devCode: issueLocalLoginCode(email) });
        return true;
      }
      set({ error: describeError(caught) });
      return false;
    } finally {
      set({ busy: false });
    }
  },

  async signInWithEmailCode(email, code) {
    set({ busy: true, error: null });
    try {
      const payload = await verifyEmailLoginCode(email, code);
      persistSession(payload);
      set({ session: payload, error: null, devCode: null });
      return true;
    } catch (caught) {
      if (serverAbsent(caught)) {
        const verdict = consumeLocalLoginCode(email, code);
        if (verdict !== "ok") {
          set({
            error:
              verdict === "expired"
                ? "验证码已过期，请重新获取。"
                : "验证码不正确，请检查后重试。",
          });
          return false;
        }
        const account = findLocalAccount(email);
        if (!account) {
          set({ error: "这台设备上还没有这个邮箱的账号，先注册一个。" });
          return false;
        }
        const session = localSession(account);
        persistSession(session);
        set({ session, error: null, devCode: null });
        return true;
      }
      set({ error: describeError(caught) });
      return false;
    } finally {
      set({ busy: false });
    }
  },

  async signOut() {
    const session = get().session;
    const token = session?.accessToken;
    persistSession(null);
    set({ session: null, error: null, devCode: null });
    if (!token || session?.local) return;
    try {
      await signOutRemote(token);
    } catch {
      // 本机会话已经清掉即可，服务器失败不阻塞退出。
    }
  },

  clearError() {
    set({ error: null, devCode: null });
  },

  setUserTheme(themeId) {
    set((state) => {
      if (!state.session) return state;
      const session = {
        ...state.session,
        user: { ...state.session.user, themeId },
      };
      persistSession(session);
      return { session };
    });
  },
}));

export async function syncThemePreference(token: string, themeId: ThemeId) {
  return updateRemoteTheme(token, themeId);
}

export type LeafiaAccount = AccountState & {
  user: AuthUser | null;
  accessToken: string | null;
  status: AccountStatus;
  /** 这个账号只活在这台设备上（没有后端可同步）。 */
  local: boolean;
};

export function useLeafiaAccount(): LeafiaAccount {
  const state = useAccountStore();
  return {
    ...state,
    user: state.session?.user ?? null,
    accessToken: state.session?.accessToken ?? null,
    status: state.session ? "signed-in" : "anonymous",
    local: Boolean(state.session?.local),
  };
}
