/**
 * 本机账号：没有后端可连的时候，「注册 / 登录」就落在这台设备上。
 *
 * 静态站点（GitHub Pages）后面没有 Fastify，`POST /v1/auth/register` 只会
 * 404。与其让注册按钮永远报「连接不到服务器」，不如把账号存在本机 ——
 * 便条、单词本本来就是这么存的。
 *
 * 口令不落盘：存的是撒了盐的指纹。这台机器上的人本来就能翻 localStorage，
 * 指纹防的是「顺手看见」，不是防攻击者；真要安全边界得靠后端。
 */
const STORAGE_KEY = "leafia:local-accounts:v1";

export interface LocalAccount {
  id: string;
  displayName: string;
  email: string;
  salt: string;
  digest: string;
  createdAt: string;
}

function readAll(): LocalAccount[] {
  if (typeof localStorage === "undefined") return [];
  try {
    const raw = JSON.parse(localStorage.getItem(STORAGE_KEY) ?? "[]");
    if (!Array.isArray(raw)) return [];
    return raw.filter(
      (entry): entry is LocalAccount =>
        Boolean(entry) &&
        typeof entry === "object" &&
        typeof (entry as LocalAccount).email === "string" &&
        typeof (entry as LocalAccount).digest === "string",
    );
  } catch {
    return [];
  }
}

function writeAll(accounts: LocalAccount[]) {
  if (typeof localStorage === "undefined") return;
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(accounts));
  } catch {
    // 隐私模式：这台设备上留不住账号，跟便条一样。
  }
}

/** 两个方向的散列拌在一起：改一个字符整串都变，取不出原文。 */
function fingerprint(salt: string, email: string, password: string) {
  const input = `${salt}:${email}:${password}`;
  let forward = 5381;
  for (let index = 0; index < input.length; index += 1) {
    forward = ((forward << 5) + forward) ^ input.charCodeAt(index);
  }
  let backward = 2166136261;
  for (let index = input.length - 1; index >= 0; index -= 1) {
    backward = Math.imul(backward ^ input.charCodeAt(index), 16777619);
  }
  return `${(forward >>> 0).toString(36)}.${(backward >>> 0).toString(36)}`;
}

function makeId(email: string) {
  let hash = 2166136261;
  for (let index = 0; index < email.length; index += 1) {
    hash = Math.imul(hash ^ email.charCodeAt(index), 16777619);
  }
  return `local-${(hash >>> 0).toString(36)}`;
}

function makeSalt() {
  if (typeof crypto !== "undefined" && "getRandomValues" in crypto) {
    const bytes = crypto.getRandomValues(new Uint8Array(8));
    return Array.from(bytes, (byte) => byte.toString(36).padStart(2, "0")).join("");
  }
  return Math.random().toString(36).slice(2, 12);
}

export function maskEmail(email: string) {
  const [name = "", domain] = email.split("@");
  if (!domain) return email;
  const head = name.slice(0, 1) || "i";
  return `${head}${"*".repeat(Math.max(3, Math.min(name.length - 1, 6)))}@${domain}`;
}

/**
 * 本机验证码。
 *
 * 静态站点后面没人发信，但「先过验证码这一关」不能省：码在本地生成、
 * 五分钟作废、用过即焚，生成后直接摆在界面上让用户抄（等于把后端开发通道
 * 的那条 devCode 搬到本机）。只活在这台设备的这个页面里，刷新就没了。
 *
 * 注册和登录各用一册：注册用的码不能拿去登录，登录用的码也不能拿来建号。
 */
const CODE_TTL_MS = 5 * 60 * 1000;

function makeCode() {
  if (typeof crypto !== "undefined" && "getRandomValues" in crypto) {
    const bytes = crypto.getRandomValues(new Uint32Array(1));
    return String(100000 + ((bytes[0] ?? 0) % 900000));
  }
  return String(Math.floor(100000 + Math.random() * 900000));
}

function createCodeBook() {
  const codes = new Map<string, { code: string; expiresAt: number }>();
  return {
    issue(email: string) {
      const code = makeCode();
      codes.set(email.trim().toLowerCase(), {
        code,
        expiresAt: Date.now() + CODE_TTL_MS,
      });
      return code;
    },
    consume(email: string, code: string): "ok" | "expired" | "invalid" {
      const key = email.trim().toLowerCase();
      const stored = codes.get(key);
      if (!stored || stored.expiresAt < Date.now()) {
        codes.delete(key);
        return "expired";
      }
      if (stored.code !== code.trim()) return "invalid";
      codes.delete(key);
      return "ok";
    },
  };
}

const registerCodes = createCodeBook();
const loginCodes = createCodeBook();

export function issueLocalRegisterCode(email: string) {
  return registerCodes.issue(email);
}

export function consumeLocalRegisterCode(
  email: string,
  code: string,
): "ok" | "expired" | "invalid" {
  return registerCodes.consume(email, code);
}

/** 本机登录验证码：只发给这台设备上已经注册过的邮箱（见 auth.ts 的 sendLoginCode）。 */
export function issueLocalLoginCode(email: string) {
  return loginCodes.issue(email);
}

export function consumeLocalLoginCode(
  email: string,
  code: string,
): "ok" | "expired" | "invalid" {
  return loginCodes.consume(email, code);
}

export function findLocalAccount(email: string) {
  const key = email.trim().toLowerCase();
  return readAll().find((entry) => entry.email === key) ?? null;
}

/** 本机注册：邮箱已经在这台设备上注册过就报重复，跟后端的 409 一个口径。 */
export function createLocalAccount(input: {
  displayName: string;
  email: string;
  password: string;
}):
  | { ok: true; account: LocalAccount }
  | { ok: false; reason: "email_registered" } {
  const email = input.email.trim().toLowerCase();
  const accounts = readAll();
  if (accounts.some((entry) => entry.email === email)) {
    return { ok: false, reason: "email_registered" };
  }
  const salt = makeSalt();
  const account: LocalAccount = {
    id: makeId(email),
    displayName: input.displayName.trim(),
    email,
    salt,
    digest: fingerprint(salt, email, input.password),
    createdAt: new Date().toISOString(),
  };
  writeAll([...accounts, account]);
  return { ok: true, account };
}

/** 本机登录：没有这个邮箱、或者口令对不上，都当作登录失败。 */
export function verifyLocalAccount(input: { email: string; password: string }) {
  const account = findLocalAccount(input.email);
  if (!account) return null;
  const digest = fingerprint(account.salt, account.email, input.password);
  return digest === account.digest ? account : null;
}
